entries[46690] = { ["name"] = "Zuckerschädel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Tag der Toten\nBenutzen: Stellt im Verlauf von 18 Sek. insgesamt 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[46691] = { ["name"] = "Totenspeise", ["text"] = "Benötigt Tag der Toten\nBenutzen: Stellt im Verlauf von 24 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und Eure Ausdauer und Willenskraft wird 15 Min. lang erhöht.\nVerkaufspreis:" }
entries[46692] = { ["name"] = "Elunes Fackel", ["text"] = "Questgegenstand" }
entries[46693] = { ["name"] = "Kleiner Papierzeppelin", ["text"] = "Questgegenstand\nBenötigt Kinderwoche\nBenutzen: Wirft den Zeppelin Eurem Waisen aus Nordend zu. (15 Sek. Abklingzeit)\n\"Genau die richtige Größe für ein kleines Kind.\"\nVerkaufspreis:" }
entries[46694] = { ["name"] = "Dellylahs gestohlene Bohnen", ["text"] = "Questgegenstand" }
entries[46695] = { ["name"] = "Smaragdgrüne Schriftrolle", ["text"] = "Questgegenstand" }
entries[46696] = { ["name"] = "Pantherfigur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: In einen pirschenden Panther verwandeln, unaufspürbar für die meisten Gegner." }
entries[46697] = { ["name"] = "Geschwollener Giftbeutel", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
entries[46698] = { ["name"] = "Mondberührter Ton", ["text"] = "Questgegenstand" }
entries[46699] = { ["name"] = "Dellylahs gestohlenes Wasser", ["text"] = "Questgegenstand" }
entries[46700] = { ["name"] = "Melithars gestohlene Taschen", ["text"] = "Questgegenstand" }
entries[46701] = { ["name"] = "Twidels improvisierter Sprengstoff", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft Twidels improvisierten Sprengstoff auf den liegengebliebenen Wagen in Höllschreis Wacht." }
entries[46702] = { ["name"] = "Uraltes Gerätefragment", ["text"] = "Questgegenstand\nEinzigartig (5)\nBenutzen: Kombiniert 5 Artefaktfragmente miteinander zu einem uralten geschlitzten Artefakt.\n\"Verkrustet mit äonenalten Ablagerungen und erst vor Kurzem zerbrochen.\"" }
entries[46703] = { ["name"] = "Messingknopf", ["text"] = "\"Ein uraltes Modell mit einem silbernen Flügelemblem.\"\nVerkaufspreis:" }
entries[46707] = { ["name"] = "Kleiner rosafarbener Dickhäuter", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick ein kleinen rosafarbenen Dickhäuter beschwören oder wieder freigeben." }
entries[46708] = { ["name"] = "Frostwyrm des tödlichen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Frostwyrm des tödlichen Gladiators oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[46709] = { ["name"] = "MiniZep-Steuerung", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört und kontrolliert Euren MiniZep. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[46710] = { ["name"] = "Rezept: Totenspeise", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (1)\nBenötigt Tag der Toten\nBenutzen: Lehrt Euch, wie man Totenspeise backt.\nVerkaufspreis:\nTotenspeise\nBenötigt Tag der Toten\nBenutzen: Stellt im Verlauf von 24 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und Eure Ausdauer und Willenskraft wird 15 Min. lang erhöht.\nVerkaufspreis:\nBenötigt Herkömmliches Mehl , Eiskalte Milch" }
entries[46711] = { ["name"] = "Seelenkerze", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Tag der Toten\nBenutzen: Platziert eine Seelenkerze, welche die Willenskraft aller in der Nähe um 4 erhöht. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[46714] = { ["name"] = "Halgas 'Straßenfeger'", ["text"] = "Questgegenstand\n\"Die Läufe dieser monströsen Waffe sind fast so dick, wie Eure Faust. Sie kann nur von einem Karawanenkodo aus angewendet werden.\"" }
entries[46715] = { ["name"] = "Geheiligte Mondsteine", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Glanz von Elunes Anmut scheint durch.\"" }
entries[46716] = { ["name"] = "Zornwurzelsamen", ["text"] = "Questgegenstand\nBenutzen: Lässt Wurzeln das Ziel würgen, bis es tot ist. Funktioniert nur bei Teufelsfelsgrellkin." }
entries[46718] = { ["name"] = "Orangefarbene Ringelblumen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Tag der Toten\nBenutzen: Gewährt 30 Sek. lang Entdeckung geringer Unsichtbarkeit. Wirkt nur am Tag der Toten. (30 Sek. Abklingzeit)\n\"Zieht angeblich Geister an und hilft dabei, am Tag der Toten mit den Seelen der Verstorbenen zu kommunizieren.\"\nVerkaufspreis:" }
entries[46719] = { ["name"] = "Horn der Jägerin", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ruft eine Jägerin der Schildwache oder schickt sie fort." }
entries[46720] = { ["name"] = "Shael'dryns Totstelltechnik", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stellt sich tot, wodurch andere erfolgreich verwirrt werden können. Hält 6 Min. lang an. Funktioniert nur im Schattenwinkel. (2 Sek., 500 Ms Abklingzeit)" }
entries[46721] = { ["name"] = "Dartols Rute", ["text"] = "Questgegenstand\nEinzigartig\n\"Die zusammengesetzte Rute fühlt sich in Eurer Hand gleichzeitig schwer und leicht an.\"" }
entries[46722] = { ["name"] = "Grol'doms Netz", ["text"] = "Questgegenstand\nBenutzen: Wirft ein Netz auf einen Plünderer der Klingenmähnen in einem Umkreis von 15 Metern. (10 Sek. Abklingzeit)" }
entries[46723] = { ["name"] = "Pilgerhut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKopf" }
entries[46725] = { ["name"] = "Rotes Erbsengewehr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Feuert eine (größtenteils) harmlose Trockenerbse ab.\n200 Aufladungen\n\"Das einzig wahre Luftdruckgewehr mit 200 Schuss Erbsenmunition, in roter Sonderedition!\"\nVerkaufspreis:" }
entries[46726] = { ["name"] = "Gefesselter Klingenmähneneber", ["text"] = "\"Er ist bewußtlos. Ihr habt ihm wirklich eine reingehauen.\"" }
entries[46734] = { ["name"] = "Schlachttriagenverbandsset", ["text"] = "Questgegenstand" }
entries[46735] = { ["name"] = "Synthebräubrille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKopf\nBenötigt Braufest\nAnlegen: Diese Brille simuliert die Effekte von Alkohol. Die Effekte können leicht entfernt werden, indem man die Brille absetzt.\n\"Die Brille, sie tut irgendetwas!\"" }
entries[46739] = { ["name"] = "Dartols Rute", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verwandelt Euch bis Abbruch lang in einen Furbolg. Kann nur im Eschental benutzt werden. (10 Sek. Abklingzeit)" }
