entries[46840] = { ["name"] = "Insigne der Frostwolf (Rang 7)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 80\nAnlegen: Erhöht Eure Abhärtungswertung um 84.\nAnlegen: Jedes Mal, wenn Ihr einem Gegner Schaden zufügt, habt ihr eine Chance, zusätzlich 390 to 450 Frostschaden zu verursachen. (Procchance: 50%, 13s Abklingzeit)\nBenutzen: Bringt Euch nach Burg Frostwolf zurück.\n\"Das Auge der Führung\"" }
