entries[46887] = { ["name"] = "Reichhaltiges Festmahl", ["text"] = "Benötigt Kochkunst (350)\nBenötigt Pilgerfreudenfest\nBenutzen: Richtet ein reichhaltiges Festmahl her, das eine sehr hungrige Gruppe sättigen kann. Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 1.108) + 8] Angriffskraft, [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.6616) + 4] Zaubermacht und [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.554) + 4] Ausdauer.\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[46888] = { ["name"] = "Reichhaltiger Korb", ["text"] = "Benötigt Kochkunst (350)\nBenötigt Pilgerfreudenfest\nBenutzen: Kombiniert Gewürzbrotfüllung, kandierte Süßkartoffeln, Moosbeerenchutney, Kürbiskuchen und einen langsam gerösteten Truthahn, um ein reichhaltiges Festmahl zu kreieren. Köstlich!\nVerkaufspreis:" }
